import { build } from 'esbuild';
import { readFile, writeFile } from 'node:fs/promises';

const result = await build({
  entryPoints: ['src/components/terminal-web/entry.ts'],
  bundle: true,
  minify: true,
  platform: 'browser',
  format: 'iife',
  target: ['es2020'],
  write: false,
});
const [bundle] = result.outputFiles;
const css = await readFile('node_modules/@xterm/xterm/css/xterm.css', 'utf8');
const generated = [
  '// Generated by `npm run build:terminal`; do not edit by hand.',
  `export const terminalJavaScript = ${JSON.stringify(bundle.text)};`,
  `export const terminalCss = ${JSON.stringify(css)};`,
  '',
].join('\n');
await writeFile('src/components/terminal-web-assets.ts', generated, 'utf8');
console.log(`Wrote terminal web assets (${bundle.text.length} JS characters, ${css.length} CSS characters).`);
